import heapq

def ferry_plan(routes, src, dst, t0):
    if src == dst:
        return (t0, 0)

    # Build adjacency list (skip useless routes a == b)
    adj = {}
    for a, b, first, every, duration in routes:
        if a == b:
            continue
        if a not in adj:
            adj[a] = []
        adj[a].append((b, first, every, duration))

    # Initialize: src at (t0, 0), all others unreachable
    best = {src: (t0, 0)}
    queue = [(t0, 0, src)]

    while queue:
        arrival, num_ferries, port = heapq.heappop(queue)

        # Skip if we already found a better path to this port
        if (arrival, num_ferries) > best.get(port, (float('inf'), float('inf'))):
            continue

        # Explore all outgoing routes
        for (dest, first, every, duration) in adj.get(port, []):
            # Compute departure time: first departure >= arrival
            if arrival < first:
                departure = first
            else:
                k = (arrival - first + every - 1) // every
                departure = first + k * every

            new_arrival = departure + duration
            new_ferries = num_ferries + 1

            # Update if this is strictly better (earlier arrival, or same arrival with fewer ferries)
            if new_arrival < best.get(dest, float('inf')) or (new_arrival == best.get(dest, float('inf')) and new_ferries < best.get(dest, float('inf'))):
                best[dest] = (new_arrival, new_ferries)
                heapq.heappush(queue, (new_arrival, new_ferries, dest))

    # Return result
    if dst in best:
        return best[dst]
    else:
        return None
