def last_link_times(n: int, cables: list[tuple[int, int, int]], pairs: list[tuple[int, int]]) -> list:
    import sys

    # Sort cables by failure time descending (latest first)
    cables_sorted = sorted(cables, key=lambda x: x[2], reverse=True)

    # Union-Find with path compression and union by rank
    parent = list(range(n))
    rank = [0] * n

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_i] = root_j
                rank[root_j] += 1
            return True
        return False

    # Process cables from latest failure to earliest
    # When a pair first becomes connected, that failure time is their answer
    answers = [None] * len(pairs)

    for cable in cables_sorted:
        a, b, fail = cable
        if union(a, b):
            # Check which pairs are now connected
            for i, (u, v) in enumerate(pairs):
                if u == v:
                    answers[i] = None
                    continue
                if find(u) == find(v):
                    answers[i] = fail

    # Fill remaining pairs with 0 (never connected)
    for i in range(len(pairs)):
        if answers[i] is None:
            answers[i] = 0

    return answers
