import math

def lit_time(beacons: list[tuple[int, int, int]], horizon: int) -> int:
    if horizon <= 0 or not beacons:
        return 0

    P = math.lcm(*beacons[0])
    for b in beacons[1:]:
        P = math.lcm(P, b[0])

    # Compute union measure for [0, P)
    # For each time t in [0, P), check which beacons are lit
    # A beacon i is lit at time t if t >= first_i and (t - first_i) % period_i < length_i

    # We'll use a sweep line approach: collect all intervals and merge them
    intervals = []
    for (period, first, length) in beacons:
        # Determine the number of flashes within [0, P)
        # A flash at time first + k*period covers [first + k*period, first + k*period + length)
        # We need to truncate at P
        num_flashes = 0
        if first < P:
            num_flashes = (P - first) // period + 1
        for k in range(num_flashes):
            start = first + k * period
            end = min(start + length, P)
            if end > start:
                intervals.append((start, end))

    # Merge overlapping intervals
    intervals.sort()
    merged = []
    for interval in intervals:
        if not merged or merged[-1][1] <= interval[0]:
            merged.append(interval)
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

    # Compute the union measure for [0, P)
    measure_P = sum(end - start for (start, end) in merged)

    # Compute how many full periods fit in horizon
    n = horizon // P
    remainder = horizon % P

    # Compute the union measure for [0, remainder)
    # We need to truncate intervals at remainder
    intervals_remainder = []
    for (start, end) in merged:
        if start < remainder:
            end = min(end, remainder)
            if end > start:
                intervals_remainder.append((start, end))

    intervals_remainder.sort()
    merged_remainder = []
    for interval in intervals_remainder:
        if not merged_remainder or merged_remainder[-1][1] <= interval[0]:
            merged_remainder.append(interval)
        else:
            merged_remainder[-1] = (merged_remainder[-1][0], max(merged_remainder[-1][1], interval[1]))

    measure_remainder = sum(end - start for (start, end) in merged_remainder)

    return n * measure_P + measure_remainder
